mapper.select:
select
museum.*,
users.nick_name,
users.head_img
from museum museum
left join users users on museum.user_id = users.id

    and museum.id = #{id}
    and museum.name like concat('%',#{name},'%')
    and museum.info = #{info}
    and museum.img = #{img}
    and museum.type = #{type}
    and museum.user_id = #{userId}
    and museum.create_time = #{createTime}
    and museum.status = #{status}
    and museum.imgs = #{imgs}
    and users.nick_name like concat('%',#{nickName},'%')
    and users.head_img = #{headImg}


    limit #{current},#{pageSize}

select count(*) from museum museum
left join users users on museum.user_id = users.id

    and museum.id = #{id}
    and museum.name like concat('%',#{name},'%')
    and museum.info = #{info}
    and museum.img = #{img}
    and museum.type = #{type}
    and museum.user_id = #{userId}
    and museum.create_time = #{createTime}
    and museum.status = #{status}
    and museum.imgs = #{imgs}
    and users.nick_name like concat('%',#{nickName},'%')
    and users.head_img = #{headImg}
